// Updates an app space. The update process is asynchronous and the status of
// the update can be checked with the GetSpaceOperation method.
func (c *internalClient) UpdateSpace(ctx context.Context, req *UpdateSpaceRequest, opts ...call.Option) (*UpdateSpaceOperation, error) {
	operation, err := c.updateSpaceBase(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	if err := validateOperationName(operation.Name); err != nil {
		return nil, err
	}
	return &UpdateSpaceOperation{
		operation:    operation,
		getOperation: c.getSpaceOperation,
	}, nil
}

// UpdateSpaceOperation tracks the state of the long-running operation started by UpdateSpace.
type UpdateSpaceOperation struct {
	operation    *Operation
	getOperation func(context.Context, *GetOperationRequest, ...call.Option) (*Operation, error)
}

// Name returns the server-assigned operation name.
func (o *UpdateSpaceOperation) Name() *string {
	return o.operation.Name
}

// Metadata returns metadata associated with the operation.
func (o *UpdateSpaceOperation) Metadata() (*SpaceUpdate, error) {
	if len(o.operation.Metadata) == 0 || bytes.Equal(bytes.TrimSpace(o.operation.Metadata), []byte("null")) {
		return nil, nil
	}
	var metadata spaceUpdateWire
	if err := json.Unmarshal(o.operation.Metadata, &metadata); err != nil {
		return nil, fmt.Errorf("decode operation metadata: %w", err)
	}
	return spaceUpdateFromWire(&metadata), nil
}

// Done refreshes the operation and reports whether it has completed.
func (o *UpdateSpaceOperation) Done(ctx context.Context, opts ...call.Option) (*bool, error) {
	operation, err := o.getOperation(ctx, &GetOperationRequest{Name: o.operation.Name}, opts...)
	if err != nil {
		return nil, err
	}
	if err := validateOperationName(operation.Name); err != nil {
		return nil, err
	}
	o.operation = operation
	return operation.Done, nil
}

// Wait polls the operation until it completes.
func (o *UpdateSpaceOperation) Wait(ctx context.Context, opts ...lro.Option) (*Space, error) {
	var result *Space
	poll := func(ctx context.Context) error {
		operation, err := o.getOperation(ctx, &GetOperationRequest{Name: o.operation.Name})
		if err != nil {
			return err
		}
		if err := validateOperationName(operation.Name); err != nil {
			return err
		}
		o.operation = operation
		if operation.Done == nil {
			return fmt.Errorf("invalid operation response: missing done field")
		}
		if !*operation.Done {
			return errOperationStillRunning
		}
		if operation.Error != nil {
			return fmt.Errorf("operation failed: %w", operation.Error)
		}
		if len(operation.Response) == 0 || bytes.Equal(bytes.TrimSpace(operation.Response), []byte("null")) {
			return fmt.Errorf("operation completed without a response")
		}
		var response spaceWire
		if err := json.Unmarshal(operation.Response, &response); err != nil {
			return fmt.Errorf("decode operation response: %w", err)
		}
		result = spaceFromWire(&response)
		return nil
	}
	if err := executeWait(ctx, poll, opts...); err != nil {
		return nil, err
	}
	return result, nil
}
